  $(this).fadeTo(500,0.4);
} else {
  $(cible).hide(&#39;slide&#39;);
  $(this).fadeTo(500,1);
}&quot; ONMOUSEOVER=&quot;this.src = &#39;/images/pathfinder/wiki/ialt.png&#39;;&quot;
ONMOUSEOUT=&quot;this.src = &#39;/images/pathfinder/wiki/ibase.png&#39;;&quot; /&gt;&lt;/td&gt;
&lt;/tr&gt;&lt;/table&gt;&lt;/div&gt;
&lt;b&gt;&#201;cole&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Pr&#233;sentation-Des-Sorts#Illusion.html&quot; title=&quot;Illusion&quot;&gt;Illusion&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Pr&#233;sentation-Des-Sorts#Fantasme.html&quot; title=&quot;Fantasme&quot;&gt;fantasme&lt;/a&gt;) [&lt;a class=&quot;pagelink&quot; href=&quot;Cr&#233;er-Un-Sort#Registre.html&quot; title=&quot;Registre&quot;&gt;effet mental, Mal&lt;/a&gt;] ; &lt;b&gt;Niveau&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Alchimiste.html&quot; title=&quot;L&amp;#39;alchimiste&quot;&gt;Alch&lt;/a&gt; 5, &lt;a class=&quot;pagelink&quot; href=&quot;Barde.html&quot; title=&quot;Le barde&quot;&gt;Bard&lt;/a&gt; 5, &lt;a class=&quot;pagelink&quot; href=&quot;Hypnotiseur.html&quot; title=&quot;L&amp;#39;hypnotiseur&quot;&gt;Hyp&lt;/a&gt; 5, &lt;a class=&quot;pagelink&quot; href=&quot;Ensorceleur.html&quot; title=&quot;L&amp;#39;ensorceleur&quot;&gt;Ens&lt;/a&gt;/&lt;a class=&quot;pagelink&quot; href=&quot;Magicien.html&quot; title=&quot;Le magicien&quot;&gt;Mag&lt;/a&gt; 5, &lt;a class=&quot;pagelink&quot; href=&quot;M&#233;dium.html&quot; title=&quot;Le m&#233;dium&quot;&gt;M&#233;d&lt;/a&gt; 4, &lt;a class=&quot;pagelink&quot; href=&quot;Psychiste.html&quot; title=&quot;Le psychiste&quot;&gt;Psy&lt;/a&gt; 5, &lt;a class=&quot;pagelink&quot; href=&quot;Spirite.html&quot; title=&quot;Le spirite&quot;&gt;Spi&lt;/a&gt; 5  
&lt;b&gt;Temps d&#39;incantation&lt;/b&gt; 10 minutes  
&lt;b&gt;Composantes&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Pr&#233;sentation-Des-Sorts#Composantes.html&quot; title=&quot;composantes&quot;&gt;V, G&lt;/a&gt;  
&lt;b&gt;Port&#233;e&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Pr&#233;sentation-Des-Sorts#Portee.html&quot; title=&quot;illimit&#233;e&quot;&gt;illimit&#233;e&lt;/a&gt;  
&lt;b&gt;Cible&lt;/b&gt; 1 cr&#233;ature vivante  
&lt;b&gt;Dur&#233;e&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Pr&#233;sentation-Des-Sorts#Duree.html&quot; title=&quot;instantan&#233;e&quot;&gt;instantan&#233;e&lt;/a&gt;  
&lt;b&gt;Jet de sauvegarde&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdesauvegarde.html&quot; title=&quot;Volont&#233;&quot;&gt;Volont&#233;&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Pr&#233;sentation-Des-Sorts.html#JETSDESAUVEGARDE&quot; title=&quot;Pr&#233;sentation des sorts&quot;&gt;annule&lt;/a&gt; (voir texte) ; &lt;b&gt;R&#233;sistance &#224; la magie&lt;/b&gt; oui
&lt;hr&gt;
Le lanceur de sort peut lancer &#224; la cr&#233;ature de son choix, qu’il nomme ou d&#233;signe, une terrifiante vision.&lt;br /&gt;&lt;br /&gt;Le &lt;i&gt;cauchemar&lt;/i&gt; emp&#234;che la cible d’atteindre la phase de sommeil r&#233;parateur et lui fait perdre 1d10 &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Pointsdevie.html&quot; title=&quot;points de vie&quot;&gt;points de vie&lt;/a&gt;. Quand la victime se r&#233;veille, elle n’est pas repos&#233;e et se retrouve dans l’incapacit&#233; de renouveler ses sorts profanes pendant vingt-quatre heures.&lt;br /&gt;&lt;br /&gt;Le &lt;a class=&quot;pagelink&quot; href=&quot;Vocabulaire-Courant#Degrededifficulte.html&quot; title=&quot;DD&quot;&gt;degr&#233; de difficult&#233;&lt;/a&gt; du &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdesauvegarde.html&quot; title=&quot;jet de sauvegarde&quot;&gt;jet de sauvegarde&lt;/a&gt; d&#233;pend de ce que le lanceur de sorts sait de sa victime et du lien physique dont il dispose (le cas &#233;ch&#233;ant).&lt;br /&gt;&lt;br /&gt;&lt;table width=&quot;100%&quot;&gt;&lt;tr&gt;&lt;td width=&quot;49%&quot;&gt;
&lt;table CLASS=&quot;tablo centre autoalt&quot;&gt;&lt;tr CLASS=&quot;titre&quot;&gt;&lt;td&gt;Connaissances&lt;/td&gt;&lt;td&gt;Modificateur au&lt;br/&gt;jet de Volont&#233;&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;Aucune*&lt;/td&gt;&lt;td&gt;+10&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;Le personnage a entendu parler du sujet&lt;/td&gt;&lt;td&gt;+5&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;Le personnage a d&#233;j&#224; rencontr&#233; le sujet&lt;/td&gt;&lt;td&gt;+0&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;Le personnage conna&#238;t bien le sujet&lt;/td&gt;&lt;td&gt;-5&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;note&quot;&gt;&lt;td COLSPAN=&quot;2&quot;&gt;&lt;i&gt;(*) Il est essentiel de poss&#233;der un lien avec une cr&#233;ature que l’on ne conna&#238;t pas.&lt;/i&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;
&lt;/td&gt;&lt;td width=&quot;2%&quot;&gt;
&lt;/td&gt;&lt;td width=&quot;49%&quot;&gt;
&lt;table CLASS=&quot;tablo centre autoalt&quot;&gt;&lt;tr CLASS=&quot;titre&quot;&gt;&lt;td&gt;Lien&lt;/td&gt;&lt;td&gt;Modificateur au&lt;br/&gt;jet de Volont&#233;&lt;/td&gt;&lt;/tr&gt;&lt;tr CLASS=&quot;premier&quot;&gt;&lt;td&gt;Portrait&lt;/td&gt;&lt;td&gt;-2&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;Possession ou v&#234;tement&lt;/td&gt;&lt;td&gt;-4&lt;/td&gt;&lt;/tr&gt;&lt;tr&gt;&lt;td&gt;Dent, m&#232;che de cheveux, rognures d’ongles, etc.&lt;/td&gt;&lt;td&gt;-10&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;
&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;br /&gt;Si &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Rejet-Du-Mal.html&quot; title=&quot;Rejet du Mal&quot;&gt;rejet du Mal&lt;/a&gt;&lt;/i&gt; est lanc&#233; sur la cible alors que le personnage lance &lt;i&gt;cauchemar&lt;/i&gt;, celui-ci est automatiquement dissip&#233; et le personnage est &lt;a class=&quot;pagelink&quot; href=&quot;&#201;tats-Pr&#233;judiciables#&#201;tourdi.html&quot; title=&quot;&#201;tourdi&quot;&gt;&#233;tourdi&lt;/a&gt; pendant dix minutes par &lt;a class=&quot;pagelink&quot; href=&quot;Lancer-Des-Sorts#Nls.html&quot; title=&quot;NLS&quot;&gt;niveau de lanceur de sorts&lt;/a&gt; de celui qui a incant&#233; &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Rejet-Du-Mal.html&quot; title=&quot;Rejet du Mal&quot;&gt;rejet du Mal&lt;/a&gt;&lt;/i&gt;.&lt;br /&gt;&lt;br /&gt;Si la cible du &lt;i&gt;cauchemar&lt;/i&gt; est &#233;veill&#233;e au moment de l’incantation, le personnage peut choisir de tout stopper (ce qui met un terme pr&#233;matur&#233; au sort) ou d’entrer en transe jusqu’&#224; ce que le sujet s’assoupisse, apr&#232;s quoi le lanceur de sorts redevient alerte et peut achever l’incantation. Si le personnage est d&#233;rang&#233; durant la transe, il doit effectuer un test de &lt;a class=&quot;pagelink&quot; href=&quot;Lancer-Des-Sorts#Concentration.html&quot; title=&quot;Concentration&quot;&gt;Concentration&lt;/a&gt;, comme s’il &#233;tait en plein milieu d’une incantation, en cas d’&#233;chec le sort est perdu.&lt;br /&gt;&lt;br /&gt;Si le personnage choisit d’entrer en transe, il n’a plus conscience de ce qui l’entoure.&lt;br /&gt;&lt;br /&gt;Il se retrouve &lt;a class=&quot;pagelink&quot; href=&quot;&#201;tats-Pr&#233;judiciables#Sansd&#233;fense.html&quot; title=&quot;Sans d&#233;fense&quot;&gt;sans d&#233;fense&lt;/a&gt;, tant physiquement que mentalement (il rate automatiquement ses jets de sauvegarde de &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdesauvegarde.html&quot; title=&quot;R&#233;flexes&quot;&gt;R&#233;flexes&lt;/a&gt; et de &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdesauvegarde.html&quot; title=&quot;Volont&#233;&quot;&gt;Volont&#233;&lt;/a&gt;, par exemple).&lt;br /&gt;&lt;br /&gt;Les cr&#233;atures qui ne dorment pas (comme les &lt;a class=&quot;pagelink&quot; href=&quot;Elfe.html&quot; title=&quot;Les elfes&quot;&gt;elfes&lt;/a&gt;, mais pas les &lt;a class=&quot;pagelink&quot; href=&quot;Demi-Elfe.html&quot; title=&quot;Les demi-elfes&quot;&gt;demi-elfes&lt;/a&gt;) ou ne r&#234;vent jamais sont insensibles &#224; &lt;i&gt;cauchemar&lt;/i&gt;.&lt;br /&gt;&lt;br /&gt;&lt;h2 class=&quot;separator&quot;&gt;Version mythique&lt;a class=&quot;headeranchor&quot; id=&quot;Version_mythique_0&quot; href=&quot;#Version_mythique_0&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h2&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.Campagnes mythiques (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Mythic Adventures, Mythic Origins/Campagnes mythiques&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoCMy.png&quot; style=&quot;opacity: 0.7&quot; loop=&quot;infinite&quot; /&gt;
&lt;/a&gt;
Les d&#233;g&#226;ts inflig&#233;s s’&#233;l&#232;vent &#224; 4d6 points et la cible est &#233;galement secou&#233;e pendant 24 heures.&lt;br /&gt;&lt;br /&gt;&lt;b&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Sorts-Mythiques.html#AMPLIFIE&quot; title=&quot;Amplifi&#233;&quot;&gt;Amplifi&#233;&lt;/a&gt; (6&#232;me).&lt;/b&gt; Le personnage peut incorporer un sort de type mental dans un &lt;a class=&quot;pagelink&quot; href=&quot;Cauchemar.html&quot; title=&quot;Destrier noir, Cauchemar&quot;&gt;cauchemar&lt;/a&gt; mythique. Le niveau maximum du sort int&#233;gr&#233; est &#233;gal &#224; la moiti&#233; du &lt;a class=&quot;pagelink&quot; href=&quot;Glossaire-Mythique#Grade.html&quot; title=&quot;Grade&quot;&gt;grade&lt;/a&gt; du personnage et le personnage doit d&#233;penser une utilisation de &lt;a class=&quot;pagelink&quot; href=&quot;Glossaire-Mythique#Pouvoirmythique.html&quot; title=&quot;pouvoir mythique&quot;&gt;pouvoir mythique&lt;/a&gt; pour chaque niveau du sort int&#233;gr&#233;, en plus de celle n&#233;cessaire pour lancer &lt;a class=&quot;pagelink&quot; href=&quot;Cauchemar.html&quot; title=&quot;Destrier noir, Cauchemar&quot;&gt;cauchemar&lt;/a&gt; mythique. Le personnage choisit si le sort int&#233;gr&#233; affecte la cr&#233;ature imm&#233;diatement ou seulement au r&#233;veil. Le sort int&#233;gr&#233; affecte une cr&#233;ature seulement, m&#234;me s’il affecte normalement plusieurs cr&#233;atures ou une zone.&lt;br /&gt;&lt;br /&gt;&lt;br /&gt;&lt;br /&gt;&lt;div class=&quot;box&quot;&gt;&lt;style&gt;.box { width: 844px; } #PageContentDiv .voiraussi h4 { line-height: 16px; }&lt;/style&gt;&lt;div class=&quot;voiraussi&quot; style=&quot;width:100%&quot;&gt;
&lt;h4 class=&quot;separator&quot;&gt;Sorts qui &#171; fonctionnent comme &#187; &lt;i&gt;cauchemar&lt;/i&gt;&lt;a class=&quot;headeranchor&quot; id=&quot;Sorts_qui_&#171;_fonctionnent_comme_&#187;_cauchemar__0&quot; href=&quot;#Sorts_qui_&#171;_fonctionnent_comme_&#187;_cauchemar__0&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h4&gt;&lt;/div&gt;
&lt;h1 class=&quot;separator&quot;&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Vision-De-Lamashtu.html&quot; title=&quot;Vision de Lamashtu&quot;&gt;Vision de Lamashtu&lt;/a&gt;&lt;a class=&quot;headeranchor&quot; id=&quot;_Vision_de_Lamashtu__1&quot; href=&quot;#_Vision_de_Lamashtu__1&quot; title=&quot;Link to this Section&quot; style=&quot;visibility: hidden;&quot;&gt;&amp;nbsp;&lt;/a&gt;&lt;/h1&gt;&lt;a href=&quot;/Wiki/Pathfinder-RPG.La Mer Int&#233;rieure (Contenu).ashx&quot; style=&quot;float:right; padding: 4px 4px 2px 8px;&quot;&gt;
&lt;img title=&quot;Source : Inner Sea World Guide/La Mer Int&#233;rieure&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Illustrations/Logos/logoISWG.gif&quot; style=&quot;opacity: 0.7&quot;/&gt;
&lt;/a&gt;&lt;b&gt;&#201;cole&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Pr&#233;sentation-Des-Sorts#Illusion.html&quot; title=&quot;Illusion&quot;&gt;Illusion&lt;/a&gt; (&lt;a class=&quot;pagelink&quot; href=&quot;Pr&#233;sentation-Des-Sorts#Fantasme.html&quot; title=&quot;Fantasme&quot;&gt;fantasme&lt;/a&gt;) [&lt;a class=&quot;pagelink&quot; href=&quot;Cr&#233;er-Un-Sort#Registre.html&quot; title=&quot;Registre&quot;&gt;effet mental, Mal&lt;/a&gt;] ; &lt;b&gt;Niveau&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Chaman.html&quot; title=&quot;Le chaman&quot;&gt;Cham&lt;/a&gt; 7, &lt;a class=&quot;pagelink&quot; href=&quot;Inquisiteur.html&quot; title=&quot;L&amp;#39;inquisiteur&quot;&gt;Inq&lt;/a&gt; 6, &lt;a class=&quot;pagelink&quot; href=&quot;Pr&#234;tre.html&quot; title=&quot;Le pr&#234;tre&quot;&gt;Pr&#234;&lt;/a&gt; 7, &lt;a class=&quot;pagelink&quot; href=&quot;Sorci&#232;re.html&quot; title=&quot;La sorci&#232;re&quot;&gt;Sor&lt;/a&gt; 7  
&lt;b&gt;Temps d’incantation&lt;/b&gt; 10 minutes (voir texte)  
&lt;b&gt;Composantes&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Pr&#233;sentation-Des-Sorts#Composantes.html&quot; title=&quot;composantes&quot;&gt;V, G&lt;/a&gt;  
&lt;b&gt;Port&#233;e&lt;/b&gt; illimit&#233;e  
&lt;b&gt;Effet&lt;/b&gt; une cr&#233;ature vivante  
&lt;b&gt;Dur&#233;e&lt;/b&gt; instantan&#233;e  
&lt;b&gt;Jet de sauvegarde&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdesauvegarde.html&quot; title=&quot;Vigueur&quot;&gt;Vigueur&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Pr&#233;sentation-Des-Sorts.html#JETSDESAUVEGARDE&quot; title=&quot;Pr&#233;sentation des sorts&quot;&gt;annule&lt;/a&gt; (voir texte) ; &lt;b&gt;R&#233;sistance &#224; la magie&lt;/b&gt; oui
&lt;hr&gt;
Ce sort fonctionne exactement comme le sort &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Sort-Cauchemar.html&quot; title=&quot;Cauchemar&quot;&gt;cauchemar&lt;/a&gt;&lt;/i&gt;. En plus des effets du cauchemar, le personnage peut utiliser un second sort qui se d&#233;clenche &#224; la fin de celui-ci. Ce deuxi&#232;me sort doit &#234;tre pr&#234;t et il faut le lancer imm&#233;diatement apr&#232;s la &lt;i&gt;vision de folie&lt;/i&gt; (ce qui, en pratique, additionne la dur&#233;e d’incantation des deux sorts). Ce deuxi&#232;me sort &#171; chevauche &#187; le cauchemar et affecte la cible d&#232;s qu’elle se r&#233;veille de son sommeil agit&#233;. On peut transmettre n’importe quel sort avec le cauchemar tant qu’il ne d&#233;passe pas le niveau 6, qu’il affecte une seule cible (la m&#234;me que celle du cauchemar) et qu’il n’inflige pas de points de d&#233;g&#226;ts. On ne tient pas compte de la port&#233;e du deuxi&#232;me sort quand il est lanc&#233; avec une &lt;i&gt;vision de folie&lt;/i&gt; et m&#234;me les attaques de contact sont consid&#233;r&#233;es comme valables (il faut tout de m&#234;me r&#233;ussir l’attaque pour affecter la cible, m&#234;me si cet acte se d&#233;roule dans le contexte du cauchemar de la victime). La cible a droit &#224; un &lt;a class=&quot;pagelink&quot; href=&quot;Valeurs-De-Combat#Jetdesauvegarde.html&quot; title=&quot;JDS&quot;&gt;jet de sauvegarde&lt;/a&gt; contre le deuxi&#232;me sort si la description de celui-ci l’y autorise. Par exemple, un pr&#234;tre de la m&#232;re des monstres peut envoyer une &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Sort-Mal&#233;diction.html&quot; title=&quot;Mal&#233;diction&quot;&gt;mal&#233;diction&lt;/a&gt;&lt;/i&gt; lors d’une &lt;i&gt;vision de folie&lt;/i&gt; mais pas une &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Barri&#232;re-De-Lames.html&quot; title=&quot;Barri&#232;re de lames&quot;&gt;barri&#232;re de lames&lt;/a&gt;&lt;/i&gt; (qui affecte une zone), ni une &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Sort-Destruction.html&quot; title=&quot;Destruction&quot;&gt;destruction&lt;/a&gt;&lt;/i&gt; (dont le niveau est trop haut) ni de &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Blessure-Mod&#233;r&#233;e.html&quot; title=&quot;Blessure mod&#233;r&#233;e&quot;&gt;blessure mod&#233;r&#233;e&lt;/a&gt;&lt;/i&gt; (qui inflige des d&#233;g&#226;ts).
&lt;/div&gt;
